// حكايات إضافية: صياغة مبسطة لمرويات موثقة، مع رابط مباشر للمصدر.
const additionalStories = [
  {id:'moses-basket',title:'موسى عليه السلام في التابوت',source:'القرآن الكريم، سورة القصص 7–13',url:'https://quran.com/28/7-13',text:'في زمن فرعون، أوحى الله إلى أم موسى أن ترضعه، فإذا خافت عليه وضعته في صندوق وألقته في النهر، وألا تخاف أو تحزن؛ فالله سيرده إليها ويجعله من المرسلين. حمل الماء الصندوق حتى وصل إلى بيت فرعون، فالتقطه آل فرعون. أرادت امرأة فرعون أن تحتفظ بالطفل، وقالت إنه قد يكون قرة عين لها وله. رفض موسى المراضع، فدلتهم أخته على امرأة ترضعه. وهكذا رد الله الطفل إلى أمه كي تقر عينها ولا تحزن. القصة في القرآن نفسه، وتعلّم أن الله قادر على حفظ عباده، وأن الأخت قد تساعد بحكمة وهدوء.'},
  {id:'moses-well',title:'موسى يساعد الفتاتين عند البئر',source:'القرآن الكريم، سورة القصص 23–28',url:'https://quran.com/28/23-28',text:'بعد أن غادر موسى مصر، وصل إلى ماء مدين، فوجد جماعة من الناس يسقون أغنامهم، ورأى فتاتين تنتظران بعيدًا لأنهما لا تزاحمان الرجال. سألهما عن شأنهما، فشرحتا أن أباهما شيخ كبير وأنهما لا تسقيان حتى ينصرف الرعاة. فسقى لهما موسى ثم تنحى إلى الظل ودعا ربه. عادت إحداهما تمشي إليه في حياء، ودعته إلى أبيها ليجزيه على مساعدته. قصّ موسى عليه السلام عليه خبره، فأمّنه الرجل، ثم عرض عليه أن يزوجه إحدى ابنتيه مقابل أن يعمل عنده سنوات. موقف قرآني عن نجدة المحتاج، والحياء، والاتفاق الواضح.'},
  {id:'moses-mission',title:'موسى يتلقى نداء ربه',source:'القرآن الكريم، سورة طه 9–36',url:'https://quran.com/20/9-36',text:'في طريقه مع أهله، رأى موسى نارًا من جانب الطور، فقال لهم أن ينتظروا لعله يأتيهم منها بقبس أو يجد عندها هداية للطريق. ناداه الله في الوادي المقدس، وعرّفه أنه رب العالمين، وأمره أن يخلع نعليه وأن يستمع إلى الوحي. سأله الله عن العصا التي بيده، فأجاب موسى بما يصنع بها، ثم أراه الله آية العصا وآية اليد. خاف موسى، فطمأنه الله وأمره أن يذهب إلى فرعون ويدعوه. طلب موسى أن يشرح الله صدره وييسر أمره، وأن يجعل أخاه هارون عونًا له. القصة تبرز الشجاعة مع طلب العون والثقة بالله.'},
  {id:'moses-magicians',title:'سحرة فرعون يختارون الإيمان',source:'القرآن الكريم، سورة الأعراف 115–126',url:'https://quran.com/7/115-126',text:'اجتمع موسى عليه السلام وسحرة فرعون أمام الناس، وطلب السحرة أن يبدأوا أو يبدأ موسى. ألقوا حبالهم وعصيهم، فخيّل إلى الناس أنها تتحرك. أوحى الله إلى موسى أن يلقي عصاه، فتحولت إلى آية أبطلت ما صنعوه. أدرك السحرة، وهم أهل خبرة بما يعرضونه، أن ما رأوه ليس سحرًا، فسجدوا لله وآمنوا برب العالمين. غضب فرعون وهددهم بالعقاب، لكنهم ثبتوا وقالوا إنهم راجعون إلى الله. لا نضيف حوارًا من عندنا؛ نلخص الآيات كما وردت. العبرة أن معرفة الحقيقة والشجاعة قد تجعلان الإنسان يختار الصواب حتى مع ضغط الآخرين.'},
  {id:'moses-sea',title:'موسى وبنو إسرائيل عند البحر',source:'القرآن الكريم، سورة الشعراء 60–68',url:'https://quran.com/26/60-68',text:'خرج موسى عليه السلام ببني إسرائيل، فلحق بهم فرعون وجنوده. وعندما رأى أصحاب موسى الجيش خلفهم والبحر أمامهم، قالوا إنهم مدركون. أجاب موسى بثقة أن ربه معه وسيهديه. فأوحى الله إليه أن يضرب البحر بعصاه، فانفلق وصار كل جانب كالجبل العظيم، ومر موسى ومن معه في طريق يابس. تبعهم فرعون بجنوده، ثم أغرقهم الله وأبقى لموسى وقومه طريق النجاة. القرآن يروي هذا الموقف الكبير بلا حاجة إلى إضافات خيالية: خوف، وثقة، وفرج بعد شدة. نتعلم أن الأمل لا يضيع، وأن المؤمن يأخذ بالأمر الذي يهديه الله إليه.'},
  {id:'yusuf-dream',title:'يوسف يخبر أباه برؤياه',source:'القرآن الكريم، سورة يوسف 4–6',url:'https://quran.com/12/4-6',text:'بدأت سورة يوسف برؤيا رآها يوسف وهو صغير، فأخبر أباه يعقوب أنه رأى أحد عشر كوكبًا والشمس والقمر يسجدون له. فهم يعقوب أن للرؤيا شأنًا، فنصحه ألا يقصها على إخوته حتى لا يكيدوا له. ثم بشره بأن الله سيجتبيه ويعلمه تأويل الأحاديث ويتم نعمته عليه. لا تذكر الآيات أن يوسف كان يعرف المستقبل كله؛ بل تنقل رؤيا وبشارة ونصيحة أب حكيم. حكاية البداية تضع الطفل أمام سؤال جميل: ماذا نفعل حين نحتاج نصيحة؟ نستمع إلى أهل الخبرة ونحفظ ما قد يسبب الحسد أو الخصام.'},
  {id:'yusuf-well',title:'يوسف في الجب وعودة القافلة',source:'القرآن الكريم، سورة يوسف 15–19',url:'https://quran.com/12/15-19',text:'اجتمع إخوة يوسف وأخذوه معهم، ثم اتفقوا أن يجعلوه في غيابة الجب. أوحى الله إلى يوسف أنه سيخبر إخوته بهذا الأمر يومًا وهم لا يشعرون. عاد الإخوة إلى أبيهم ليلًا يبكون، وقالوا إن الذئب أكله، وأروه قميصه بدم كذب. لم يصدق يعقوب الخبر كما حكوه، واستعان بالصبر الجميل. وبعد ذلك جاءت قافلة، فأرسلوا من يستقي الماء، فلما أدلى دلوه وجد يوسف، فأخفوه في متاعهم وأخذوه معهم. يصور القرآن الابتلاء ثم باب النجاة، من غير أن نخترع تفاصيل عن حياة يوسف في البئر.'},
  {id:'yusuf-prison',title:'يوسف يفسر رؤيا صاحبيه في السجن',source:'القرآن الكريم، سورة يوسف 36–42',url:'https://quran.com/12/36-42',text:'دخل السجن مع يوسف فتيان، وقص كل واحد منهما رؤياه. قبل أن يفسرها، دعاهما يوسف إلى عبادة الله وحده وبيّن لهما أن الحكم لله. ثم أخبرهما بتأويل ما رأيا: أحدهما يعود فيسقي سيده، والآخر يصلب فتأكل الطير من رأسه. وطلب من الذي ظن أنه ناجٍ أن يذكره عند سيده، لكنه نسي، فبقي يوسف في السجن بضع سنين. يعرض القرآن يوسف عالمًا وصابرًا، يستغل وقته في الدعوة والإحسان، ولا يترك رسالته حتى وهو في مكان ضيق. الحكاية تعلم أن الظروف الصعبة لا تمنع الإنسان من فعل الخير.'},
  {id:'yusuf-king-dream',title:'رؤيا الملك وتدبير يوسف',source:'القرآن الكريم، سورة يوسف 43–57',url:'https://quran.com/12/43-57',text:'رأى ملك مصر سبع بقرات سمان يأكلهن سبع عجاف، وسبع سنبلات خضر وأخر يابسات، ولم يجد من يفسر الرؤيا. تذكر ساقي الملك يوسف، فجاءه يسأله. فسّر يوسف الرؤيا بسنوات خصب يعقبها قحط، وأرشد إلى حفظ ما يحصد الناس إلا قليلًا مما يأكلون. طلب يوسف أن يُسأل عن قضية النسوة قبل أن يخرج، حتى تظهر براءته. وبعد التحقيق عُرف صدقه وأمانته، فجعله الملك على خزائن الأرض. قصة قرآنية طويلة عن العلم والتخطيط وحسن إدارة الموارد، لا عن معجزة تبرر الكسل؛ فقد قدم يوسف فهمًا وخطة عملية للسنوات القادمة.'},
  {id:'yusuf-reunion',title:'يوسف يلتقي إخوته ثم أبويه',source:'القرآن الكريم، سورة يوسف 58–101',url:'https://quran.com/12/58-101',text:'جاء إخوة يوسف إلى مصر يطلبون الطعام في سنوات القحط، ولم يعرفوه، لكنه عرفهم. أعطاهم حاجتهم وطلب أن يأتوه بأخيهم في المرة المقبلة. تتابعت الأحداث حتى عاد يعقوب وبنوه إلى مصر، وكشف يوسف عن هويته. لم ينتقم من إخوته، بل قال إنه لا تثريب عليهم، وسأل الله أن يغفر لهم. أرسل قميصه إلى أبيه، فعاد بصر يعقوب حين أُلقي عليه، ثم اجتمعت الأسرة. عندئذ ذكر يوسف أباه بالرؤيا القديمة، وأتم الله نعمته عليه. نهاية سورة يوسف تبرز العفو بعد القدرة، والصبر الطويل، ولمّ شمل الأسرة.'},
  {id:'younus-prayer',title:'يونس عليه السلام في الظلمات',source:'القرآن الكريم، سورة الأنبياء 87–88',url:'https://quran.com/21/87-88',text:'ذهب يونس عليه السلام مغاضبًا، وظن أن الله لن يضيق عليه، ثم نادى في الظلمات معترفًا بوحدانية الله ومنزهًا له، ومقرًا بأنه كان من الظالمين. استجاب الله له ونجاه من الغم، وبيّن القرآن أن الله ينجي المؤمنين كذلك. لا نضيف وصفًا لم يرد عن شكل البحر أو الحوت، بل نركز على الدعاء والتوبة والفرج. تتعلم الأسرة من القصة أن الإنسان إذا أخطأ لا يصر على الخطأ؛ يرجع إلى الله، يعترف بتقصيره، ويطلب العون. والأمل يبقى موجودًا حتى في أشد اللحظات.'},
  {id:'ayyub-patience',title:'أيوب عليه السلام والصبر وقت المرض',source:'القرآن الكريم، سورة الأنبياء 83–84',url:'https://quran.com/21/83-84',text:'ابتلى الله أيوب عليه السلام بالضر، فدعا ربه بأدب ورحمة، وذكر أنه مسه الضر وأن الله أرحم الراحمين. لم يذكر القرآن تفاصيل المرض أو مدة البلاء، لذلك لا نضيفها. استجاب الله له، فكشف ما به من ضر، ورد عليه أهله ومثلهم معهم، وجعل ذلك رحمة وذكرى للعابدين. حكاية قصيرة في عدد آياتها، عظيمة في معناها: يمكن للإنسان أن يدعو الله حين يتألم، وأن يصبر ويطلب العلاج والمساندة من أهله. والله يسمع دعاء عباده ويعلم ما يمرون به.'},
  {id:'maryam-news',title:'مريم تتلقى البشارة بعيسى',source:'القرآن الكريم، سورة مريم 16–26',url:'https://quran.com/19/16-26',text:'اعتزلت مريم أهلها إلى مكان شرقي، فأرسل الله إليها روحه في صورة بشر سوي. استعاذت بالرحمن، فأخبرها أنه رسول ربها ليهب لها غلامًا زكيًا. تعجبت مريم كيف يكون لها غلام ولم يمسسها بشر، فجاءها الجواب أن الأمر على الله هين. حملت مريم وابتعدت عن الناس حتى جاءها المخاض عند جذع النخلة، فواساها الله وأمرها أن تهز الجذع ليُساقط عليها رطبًا، وأن تأكل وتشرب وتقر عينًا. نقتصر على ما تقوله الآيات: البشارة والولادة والتيسير. القصة تعلم اللجوء إلى الله، وطلب السكينة وقت الخوف.'},
  {id:'maryam-baby',title:'عيسى عليه السلام يتكلم في المهد',source:'القرآن الكريم، سورة مريم 27–33',url:'https://quran.com/19/27-33',text:'عادت مريم إلى قومها تحمل عيسى عليه السلام، فاستغربوا وأشاروا إليها بالطفل. لم تجادلهم، بل أشارت إلى عيسى. قالوا كيف يكلمون طفلًا في المهد؟ فتكلم عيسى بإذن الله، وعرّف بنفسه عبدًا لله، وأن الله آتاه الكتاب وجعله نبيًا، وأوصاه بالصلاة والزكاة والبر بوالدته. انتهى كلامه بالسلام عليه يوم ولد ويوم يموت ويوم يبعث حيًا. الآيات تروي آية عظيمة وتدافع عن مريم، من غير إضافة حوار بشري إليها. المغزى أن الله يكرم عباده الصالحين، وأن بر الوالدة خلق جليل.'},
  {id:'sulayman-hoopoe',title:'سليمان والهدهد وخبر سبأ',source:'القرآن الكريم، سورة النمل 20–28',url:'https://quran.com/27/20-28',text:'تفقد سليمان عليه السلام الطير فلم يجد الهدهد، فقال إنه سيتثبت من غيابه. لم يطل غياب الهدهد، بل جاء بخبر مهم عن مملكة سبأ وملكة تحكمها، وأن قومها يسجدون للشمس من دون الله. قال سليمان إنه سيتحقق من صدق الخبر، ثم كتب رسالة وأرسلها مع الهدهد. طلب من الهدهد أن يلقيها إليهم وينظر ماذا يرجعون. هذه حكاية عن قائد يتثبت من الأخبار قبل أن يحكم، وعن طائر يؤدي مهمة دقيقة. يعلّمنا القرآن ألا ننقل كل ما نسمع فورًا، وأن نبحث عن صحة الخبر.'},
  {id:'sulayman-bilqis',title:'ملكة سبأ تستمع إلى الرسالة',source:'القرآن الكريم، سورة النمل 29–44',url:'https://quran.com/27/29-44',text:'قرأت ملكة سبأ رسالة سليمان على الملأ، ووصفتها بأنها كتاب كريم، ثم استشارت قومها قبل أن تقرر. أرسلت هدية، لكن سليمان أوضح أن ما آتاه الله خير مما عندهم، ودعاها إلى القدوم. في القصر، نقل عرشها بإذن الله، ثم اختبرها في مشهد الصرح الممرد من قوارير. أدركت الملكة حقيقة ما رأت، وأعلنت أنها ظلمت نفسها وأسلمت مع سليمان لله رب العالمين. القرآن يسرد رحلة قرارها من قراءة الرسالة إلى طلب المشورة، ثم التفكير في العلامات، بلا سرد خيالي. المغزى أن الحكمة تستمع وتتشاور وتراجع رأيها.'},
  {id:'cave-youth',title:'فتية الكهف يختارون الإيمان',source:'القرآن الكريم، سورة الكهف 9–26',url:'https://quran.com/18/9-26',text:'كان فتية في زمن قديم يؤمنون بربهم، فزادهم الله هدى وثبّت قلوبهم. اعتزلوا قومهم ولجأوا إلى الكهف، ودعوا الله أن يهيئ لهم من أمرهم رشدًا. أنامهم الله سنين طويلة، ثم بعثهم ليتساءلوا كم لبثوا، وأرسلوا واحدًا منهم إلى المدينة بورقهم ليبحث عن طعام طيب، مع الحذر في تصرفه. أراد الله أن يظهر قصتهم للناس لتكون آية على البعث. يحكي القرآن ما نعرفه عن قرارهم وثباتهم ونومهم ثم استيقاظهم، ولا يذكر أسماءهم ولا عددهم على وجه القطع؛ لذلك لا نخترع أسماء. القصة تركز على صحبة تعين على الإيمان.'},
  {id:'nuh-ark',title:'نوح عليه السلام والسفينة',source:'القرآن الكريم، سورة هود 36–48',url:'https://quran.com/11/36-48',text:'أوحى الله إلى نوح عليه السلام أنه لن يؤمن من قومه إلا من قد آمن، وأمره أن يصنع السفينة. كلما مر عليه جماعة من قومه سخروا منه، لكنه واصل العمل بأمر الله. وعندما جاء أمر الله وفار التنور، حمل نوح في السفينة من كل زوجين اثنين وأهله والمؤمنين، إلا من سبق عليه القول. جرت السفينة بهم في موج كالجبال، ونادى نوح ابنه أن يركب معهم، لكنه اختار ألا يفعل. بعد انتهاء الأمر استقرت السفينة على الجودي، وقيل لنوح أن يهبط بسلام وبركات. قصة فيها عمل طويل، وثبات، واختيارات صعبة.'},
  {id:'luqman-advice',title:'لقمان يوصي ابنه',source:'القرآن الكريم، سورة لقمان 12–19',url:'https://quran.com/31/12-19',text:'آتَى الله لقمان الحكمة، فشكر الله. ومن وصاياه لابنه ألا يشرك بالله، وذكّره أن الله يعلم كل شيء ولو كان صغيرًا وخفيًا. أوصاه بإقامة الصلاة، والأمر بالمعروف، والنهي عن المنكر، والصبر على ما يصيبه. ثم علمه حسن معاملة والديه، والتواضع للناس، وألا يمشي في الأرض مرحًا، وأن يعتدل في مشيه ويخفض صوته. لم يذكر القرآن اسم الابن أو مكان الحوار، فلا نضيف تفاصيل عن البيت أو الطريق. هذه قصة وصايا من أب حكيم لابنه، يمكن أن يقرأها الوالدان مع الطفل ويتحدثا عن كل خلق في يومه.'},
  {id:'ibrahim-idols',title:'إبراهيم عليه السلام يسأل قومه عن الأصنام',source:'القرآن الكريم، سورة الأنبياء 51–67',url:'https://quran.com/21/51-67',text:'آتَى الله إبراهيم رشده من قبل، فسأل أباه وقومه عن التماثيل التي يعبدونها. أخبروه أنهم وجدوا آباءهم يفعلون ذلك. قال إنه جاد في بيان أن ربهم هو رب السماوات والأرض، لا التماثيل التي لا تسمع ولا تنفع. ولما رجع القوم إلى عيدهم، كسر الأصنام وجعل كبيرها باقيا، حتى يسألهم إن كانت تنطق. عادوا إلى أنفسهم وقالوا إن الأصنام لا تتكلم، ثم رجعوا إلى خصامهم. أراد إبراهيم أن يدعوهم للتفكر، لا أن يصنع حكاية للتسلية. المغزى أن نبحث عن الحق بعقل، وألا نتبع عادة لمجرد أن الآخرين يفعلونها.'},
  {id:'ibrahim-fire',title:'الله ينجي إبراهيم من النار',source:'القرآن الكريم، سورة الأنبياء 68–70',url:'https://quran.com/21/68-70',text:'بعد أن حاجّ إبراهيم عليه السلام قومه في شأن الأصنام، غضبوا وقالوا أن يحرقوه وينصروا آلهتهم. جعلوا الأمر حرقًا بالنار، لكن الله قال للنار أن تكون بردًا وسلامًا على إبراهيم. أرادوا به كيدًا، فجعلهم الله الأخسرين. لا نضيف تفاصيل عن كيفية إشعال النار أو مدتها أو ما قيل فيها، لأن الآيات لم تذكر ذلك. القصة الموثقة تعلم أن إبراهيم ثبت على التوحيد، وأن الله قادر على نصر من يشاء. يمكن للطفل أن يفهم الشجاعة هنا على أنها قول الحق بأدب والثبات على عبادة الله.'},
  {id:'ibrahim-guests',title:'ضيوف إبراهيم عليه السلام',source:'القرآن الكريم، سورة الذاريات 24–30',url:'https://quran.com/51/24-30',text:'جاءت إلى إبراهيم عليه السلام أخبار ضيوف مكرمين. دخلوا عليه فسلموا، فرد السلام، ثم ذهب إلى أهله فجاء بعجل سمين وقربه إليهم، فلما رآهم لا يأكلون خاف منهم. طمأنوه وأخبروه أنهم رسل من الله، وبشروه بغلام عليم. كانت زوجته قائمة فضحكت، فبشروها بإسحاق ومن وراء إسحاق يعقوب. تعجبت من البشارة لكبر سنها، فأخبروها أن ذلك من أمر الله. يروي القرآن اللقاء والضيافة والبشارة بوضوح، دون وصف منزل إبراهيم أو لباس الضيوف. المغزى إكرام الضيف، وأن الخير قد يأتي بعد ما نظنه بعيدًا.'},
  {id:'ayyub-family',title:'أيوب يرجع إلى أهله بعد البلاء',source:'القرآن الكريم، سورة ص 41–44',url:'https://quran.com/38/41-44',text:'في سورة ص، دعا أيوب عليه السلام ربه بعد أن مسه الشيطان بنصب وعذاب. أمره الله أن يضرب برجله، فظهر ماء بارد يغتسل منه ويشرب، وأزال الله ما به من ضر، ورد عليه أهله ومثلهم معهم رحمة من الله وذكرى لأولي الألباب. ثم وجّهه الله في أمر يمينه وأن يبر بها بطريقة رحيمة. لا تذكر الآيات تفاصيل أيام المرض أو أسماء أفراد الأسرة، لذلك تبقى حكايتنا عند حدود النص. نرى فيها دعاء أيوب، واستجابة ربه، وعودة العافية والأهل. مغزاها الصبر واللجوء إلى الله مع الفرج.'},
  {id:'hajar-valley',title:'هاجر وإسماعيل في الوادي',source:'صحيح البخاري، حديث 3364',url:'https://sunnah.com/bukhari:3364',text:'يروي ابن عباس رضي الله عنهما أن إبراهيم عليه السلام جاء بهاجر وابنها إسماعيل إلى موضع عند البيت، ولم يكن في المكان يومها ماء ولا ناس. ترك عندهما جرابًا فيه تمر وسقاءً فيه ماء، ثم همّ بالرحيل. تبعته هاجر وسألته أكثر من مرة: أالله أمرك بهذا؟ فلما علمت أن الأمر من الله قالت إنها تثق أن الله لن يضيعهما. كانت بداية ابتلاء صعب، لكن قلبها تعلّق بالله، وبقيت الأم إلى جوار طفلها تواجه الموقف بشجاعة ويقين.'},
  {id:'hajar-search',title:'هاجر تبحث عن الماء بين الصفا والمروة',source:'صحيح البخاري، حديث 3364',url:'https://sunnah.com/bukhari:3364',text:'نفد الماء، واشتد العطش على إسماعيل الصغير. لم تستسلم هاجر، فصعدت الصفا تنظر هل ترى أحدًا، ثم نزلت وسعت إلى المروة، وعادت تكرر السعي سبع مرات. كانت تبحث عن سبب ينقذ طفلها، وتعمل بكل ما تستطيع بدل أن تقف خائفة. لم تجد إنسانًا عند الجبلين، لكنها واصلت المحاولة حتى جاءها الفرج من حيث لا تتوقع. يعلّمنا هذا الموقف أن التوكل لا يعني ترك السعي، وأن الأم المحبة تبذل جهدها وتصبر.'},
  {id:'zamzam',title:'ماء زمزم يظهر لإسماعيل',source:'صحيح البخاري، حديث 3364',url:'https://sunnah.com/bukhari:3364',text:'بعد سعي هاجر بين الصفا والمروة، سمعت صوتًا عند موضع إسماعيل. فإذا بجبريل عليه السلام يضرب الأرض عند زمزم، فظهر الماء. أسرعت هاجر تجمع التراب حوله وتحجز الماء بيديها، وتغرف منه في سقاءها. قال النبي ﷺ إن أم إسماعيل لو تركت زمزم لكانت عينًا جارية. شربت هاجر ورضيعها، وصار الماء سببًا لحياة المكان. هذه خاتمة موقف جمع الصبر والعمل والفرج، وتذكّر الطفل أن الله يفتح أبوابًا بعد أن نظن أن الأسباب انتهت.'},
  {id:'zamzam-caravan',title:'القافلة التي نزلت عند زمزم',source:'صحيح البخاري، حديث 3364',url:'https://sunnah.com/bukhari:3364',text:'مرّت جماعة من قبيلة جرهم بالقرب من مكة، فرأوا طائرًا يطير حول المكان، فعرفوا أن الطيور لا تدور عادةً حول ماء إلا حيث تجده. أرسلوا من يستطلع، فعادوا يخبرونهم بوجود الماء. استأذنوا هاجر أن يسكنوا قريبًا منها، فوافقت على أن يكون لهم حق الانتفاع بالماء من غير أن يملّكهم إياه. كبر إسماعيل بين جيران يتكلمون العربية، وتعلّم لغتهم. يروي الحديث كيف صار المكان الخالي موطنًا مأهولًا، وكيف يمكن لحسن الجوار والاتفاق الواضح أن يجمع الناس.'},
  {id:'kaaba-build',title:'إبراهيم وإسماعيل يرفعان قواعد الكعبة',source:'صحيح البخاري، حديث 3364',url:'https://sunnah.com/bukhari:3364',text:'لما كبر إسماعيل، عاد إبراهيم عليه السلام إلى مكة، والتقى ابنه عند زمزم. أخبره أنه مأمور بأمر، فسأله إسماعيل أن يعينه. قال إبراهيم إن الله أمره أن يبني هنا بيتًا، فأجابه ابنه: افعل ما أمرك الله. عملا معًا في البناء، وكان إسماعيل يناوله الحجارة وإبراهيم يضعها. لم يكن العمل فرديًا؛ أب وابنه يتعاونان في طاعة الله. ويذكر القرآن دعاءهما بالقبول. المغزى أن التعاون بين الأهل يصنع أثرًا طيبًا، وأن العمل الصالح يحتاج إخلاصًا وصبرًا.'},
  {id:'first-revelation',title:'أول لقاء في غار حراء',source:'صحيح البخاري، حديث 3',url:'https://sunnah.com/bukhari:3',text:'كان النبي محمد ﷺ يحب الخلوة في غار حراء، فيتعبد الليالي. وفي إحدى الليالي جاءه المَلَك فقال له: اقرأ. أجاب النبي ﷺ أنه لا يقرأ، فضمه المَلَك ثم أرسله، وكرر ذلك ثلاث مرات، ثم تلا عليه أول آيات سورة العلق. عاد النبي ﷺ إلى خديجة رضي الله عنها وقلبه يرجف، وقال: زملوني. لم يحوّل الراوي الخبر إلى حوار متخيّل؛ هذه هي التفاصيل التي نقلها الحديث. كانت بداية نزول الوحي، وأول كلمة فيها دعوة إلى القراءة والتعلم.'},
  {id:'khadija-support',title:'خديجة تطمئن النبي ﷺ',source:'صحيح البخاري، حديث 3',url:'https://sunnah.com/bukhari:3',text:'عاد النبي ﷺ من غار حراء بعد أول لقاء بالوحي، وطلب من خديجة رضي الله عنها أن تدثره. أخبرها بما حدث وبأنه خشي على نفسه. لم تسخر منه ولم تتركه وحده؛ طمأنته وذكّرته بصفاته الطيبة: صلته للرحم، وصدقه، ومساعدته للمحتاج، وإكرامه للضيف. ثم أخذته إلى ورقة بن نوفل، فسمع منه ما عرفه عن الوحي. يبرز الموقف كيف كان الإصغاء والطمأنة سندًا وقت الخوف، وكيف جمعت خديجة بين الحنان والحكمة وطلب المشورة من أهل العلم.'},
  {id:'hijra-cave',title:'النبي ﷺ وأبو بكر في الغار',source:'صحيح البخاري، حديث 3905',url:'https://sunnah.com/bukhari:3905',text:'حين خرج النبي ﷺ وأبو بكر رضي الله عنه مهاجرين، اختبآ في غار ثور أيامًا، وكان عبد الله بن أبي بكر يأتيهما بأخبار مكة ليلًا، ثم يرجع قبل الصباح. وكانت أسماء بنت أبي بكر تجهز لهما الطعام، ويأتي عامر بن فهيرة بالغنم ليمحو آثار الطريق. يذكر الحديث هذه الأعمال الدقيقة التي تعاون فيها أهل البيت على حفظ السر، مع أخذ الأسباب والتخطيط. وفي الغار قال النبي ﷺ لصاحبه ألا يحزن، فكان التوكل مصحوبًا بالهدوء والثبات.'},
  {id:'asma-provisions',title:'أسماء بنت أبي بكر وتجهيز الزاد',source:'صحيح البخاري، حديث 3905',url:'https://sunnah.com/bukhari:3905',text:'في أيام الهجرة الصعبة، كانت أسماء بنت أبي بكر رضي الله عنها تذهب بالطعام إلى النبي ﷺ وأبيها في غار ثور. احتاجا إلى ربط الزاد، فشقّت نطاقها نصفين وربطت بهما الطعام، فسماها النبي ﷺ ذات النطاقين. ينقل الحديث هذا التفصيل الصغير الذي يكشف شجاعة فتاة شابة ومساهمتها في موقف عظيم. لم تكن تحمل سيفًا أو تقود جماعة؛ لكنها أدت ما تستطيع بإتقان. نتعلم أن خدمة الآخرين والعمل المناسب لكل شخص قد يكون له أثر كبير.'},
  {id:'suraqa',title:'سراقة يلاحق رحلة الهجرة',source:'صحيح البخاري، حديث 3906',url:'https://sunnah.com/bukhari:3906',text:'خرج سراقة بن مالك يبحث عن النبي ﷺ وأبي بكر رضي الله عنهما، بعدما سمع أن قريشًا تطلبهما. اقترب من مكانهما، لكن فرسه ساخت قوائمها في الأرض، فعرف أن الأمر ليس كما أراد. طلب الأمان، وكتب له أبو بكر كتابًا، فعاد سراقة يكتم خبرهما عن الناس ويمنع من يطلبهما من متابعتهما. يحكي الحديث كيف تحوّل مطارد إلى حامٍ للطريق بعد أن أخذ عهدًا بالأمان. العبرة أن الأمانة والوفاء بالعهد يغيران مجرى المواقف.'},
  {id:'hudaybiya',title:'الصحابة عند صلح الحديبية',source:'صحيح البخاري، حديث 2731',url:'https://sunnah.com/bukhari:2731',text:'خرج النبي ﷺ وأصحابه يريدون العمرة، فمنعتهم قريش من دخول مكة، ثم جرت مفاوضات طويلة انتهت بصلح الحديبية. كانت بعض شروط الصلح شاقة على الصحابة، لكن النبي ﷺ قبلها لما فيها من حقن الدماء والهدنة. وبعد كتابة الصلح طلب منهم أن ينحروا هديهم ويحلقوا، فتأخروا من شدة ما وجدوا في نفوسهم. دخل النبي ﷺ على أم سلمة رضي الله عنها يستشيرها، فأشارت عليه أن يبدأ بنفسه. فعل ذلك، فاقتدى به الناس. نتعلم أن القدوة الهادئة والمشورة الحكيمة تساعدان وقت التوتر.'},
  {id:'umm-salama-advice',title:'مشورة أم سلمة يوم الحديبية',source:'صحيح البخاري، حديث 2731',url:'https://sunnah.com/bukhari:2731',text:'بعد الصلح، كان الصحابة ينتظرون أن يعودوا إلى مكة، لكنهم أُمروا أن ينحروا الهدي ويحلقوا رؤوسهم. من شدة الحزن لم يبادروا فورًا، فدخل النبي ﷺ على أم سلمة رضي الله عنها وأخبرها بما رأى. اقترحت أن يخرج فينحر هديه ويحلق، من غير أن يطلب من أحد أن يبدأ. عمل برأيها، فلما رآه الصحابة يفعل ذلك قاموا ونحروا وحلقوا. لا تضيف الرواية كلمات لم ترد؛ لكنها تثبت قيمة المشورة والعمل بالحل العملي. الموقف يعلّمنا أن التصرف الهادئ قد يساعد الجماعة على تجاوز الحيرة.'},
  {id:'jabir-camel',title:'جمل جابر يعود إليه هدية',source:'صحيح البخاري، حديث 2718',url:'https://sunnah.com/bukhari:2718',text:'كان جابر بن عبد الله رضي الله عنهما في سفر على جمل متعب بطيء، فلحق به النبي ﷺ، ودعا للجمل وضربه ضربة خفيفة، فصار نشيطًا يمشي أسرع مما اعتاد جابر. عرض النبي ﷺ شراءه، فوافق جابر واشترط أن يركبه حتى يصل إلى أهله. وعندما وصل، أعطاه النبي ثمنه، ثم أرسل إليه ليعيد له الجمل أيضًا. يروي جابر أن المال والجمل صارا له. حكاية عن اللطف والكرم ومراعاة حاجة شاب فقد أباه وكان يعول أخواته.'},
  {id:'abu-bakr-guests',title:'ضيافة أبي بكر وأصحاب الصفة',source:'صحيح البخاري، حديث 602',url:'https://sunnah.com/bukhari:602',text:'استضاف عبد الرحمن بن أبي بكر عددًا من أصحاب الصفة، وطلب منه أبوه أبو بكر أن يعتني بهم حتى يعود. تأخر أبو بكر عند النبي ﷺ، فامتنع الضيوف عن الطعام حتى يرجع مضيفهم. عاد أبو بكر منزعجًا لأنهم لم يأكلوا، ثم اجتمعوا على العشاء. يذكر الراوي أن الطعام زاد حتى أكلوا وشبعوا، ثم حمل أبو بكر ما بقي إلى النبي ﷺ. في القصة اهتمام بالضيف، ووفاء المضيف، وحرص الأسرة على ألا يبقى أحد جائعًا.'},
  {id:'abu-talha-guest',title:'أبو طلحة يكرم ضيف النبي ﷺ',source:'صحيح البخاري، حديث 3798',url:'https://sunnah.com/bukhari:3798',text:'جاء رجل إلى النبي ﷺ يطلب طعامًا، فلم يكن عنده ما يقدمه، فسأل أصحابه من يستضيفه. قام أبو طلحة رضي الله عنه وأخذه إلى بيته، ولم يكن عند أسرته إلا طعام قليل يكفي الأطفال. اتفق مع زوجته أن تنوّم الصغار وتقدم الطعام للضيف، وأن تخفت السراج حتى يظن الضيف أن الجميع يأكل معه. أكل الضيف، وبات أهل البيت جائعين. وفي الصباح أخبر النبي ﷺ أبا طلحة أن الله رضي عن صنيعهما. موقف مؤثر عن الإيثار والضيافة.'},
  {id:'dog-thirsty-man',title:'رجل يسقي كلبًا عطشانًا',source:'صحيح البخاري، حديث 3321',url:'https://sunnah.com/bukhari:3321',text:'أخبر النبي ﷺ عن رجل كان يمشي في طريق فاشتد به العطش، فوجد بئرًا فنزل فيها وشرب. وعندما خرج رأى كلبًا يلهث من العطش ويأكل التراب الرطب. تذكر الرجل عطشه، فعاد إلى البئر وملأ خفه ماءً، ثم أمسكه بفمه وصعد، فسقى الكلب. أخبر النبي ﷺ أن الله شكر له وغفر له. وعندما سأل الصحابة عن الإحسان إلى الحيوان، بيّن لهم أن في كل كبد رطبة أجرًا. قصة كاملة تعلم الطفل أن الرحمة تشمل كل مخلوق.'},
  {id:'woman-dog',title:'امرأة رحمت كلبًا عطشانًا',source:'صحيح البخاري، حديث 3467',url:'https://sunnah.com/bukhari:3467',text:'يروي النبي ﷺ خبر امرأة من بني إسرائيل وجدت كلبًا يطوف حول بئر، وقد أرهقه العطش. لم يكن معها إناء، فخلعت خفها ودلته في البئر، ثم أمسكت به حتى ملأته ماءً، وسقت الكلب. لم تكن الرحمة في كلام كبير؛ كانت في ملاحظة مخلوق ضعيف والبحث عن طريقة لمساعدته بما تملكه. يذكر الحديث أن الله غفر لها بسبب ذلك العمل. القصة تفتح بابًا للحديث مع الطفل عن الرفق بالحيوان، وتؤكد أن المعروف الصغير قد يكون عظيمًا عند الله.'},
  {id:'cat-woman',title:'قصة المرأة التي حبست قطة',source:'صحيح البخاري، حديث 3318',url:'https://sunnah.com/bukhari:3318',text:'حكى النبي ﷺ عن امرأة حبست قطة، فلم تطعمها ولم تتركها تبحث عن طعامها. ظلت القطة محرومة حتى ماتت، فاستحقت المرأة الوعيد بسبب قسوتها. لا تذكر الرواية اسم المرأة ولا تفاصيل أخرى، لذلك لا نخترع لها اسمًا أو حوارًا. لكنها تعطينا قصة واضحة يفهمها الصغير: الحيوان أمانة، ومن يختار تربيته يجب أن يوفر له الطعام والرعاية، ولا يجوز أن يؤذيه أو يتركه جائعًا. المغزى أن الرحمة مسؤولية وعمل يومي.'},
  {id:'remove-harm',title:'إزالة غصن يؤذي المارة',source:'صحيح مسلم، حديث 1914',url:'https://sunnah.com/muslim:1914',text:'أخبر النبي ﷺ عن رجل وجد غصنًا شائكًا في طريق الناس، فأزاله حتى لا يصيب أحدًا. لم يكن يعرف من سيمر بعده، ولم ينتظر أن يشكره أحد؛ رأى أذى محتملًا فرفعه عن الطريق. ذكر النبي ﷺ أن الله شكر له هذا العمل وغفر له. ثم بيّن أن شعب الإيمان كثيرة، ومنها إماطة الأذى عن الطريق. قصة قصيرة في كلماتها، كبيرة في معناها: قد تكون مساعدة الناس في عمل بسيط لا يراه أحد، مثل إبعاد حجر أو تنبيههم إلى خطر.'},
  {id:'lenient-debtor',title:'تاجر يرفق بالمدينين',source:'صحيح البخاري، حديث 2078',url:'https://sunnah.com/bukhari:2078',text:'ذكر النبي ﷺ أن رجلًا كان يتعامل مع الناس في القروض، وكان يقول لمن يعمل عنده: إذا وجدتم مدينًا لا يقدر على السداد، فتجاوزوا عنه، لعل الله أن يتجاوز عنا. فلما لقي الله غفر له. لا تحكي الرواية عن ثروة الرجل أو اسمه، فلا نضيف ذلك. جوهر الموقف أن التاجر لم يجعل المال أهم من الرحمة، وأعطى المتعثر وقتًا وفرصة. نتعلم أن إنظار المحتاج والتسامح عند القدرة من الأخلاق التي يحبها الله.'},
  {id:'debt-dispute',title:'النبي ﷺ يصلح بين متخاصمين في دَين',source:'صحيح البخاري، حديث 2705',url:'https://sunnah.com/bukhari:2705',text:'سمعت عائشة رضي الله عنها أصوات رجلين يتنازعان عند باب بيتها. كان أحدهما يطلب من الآخر أن يخفف عنه بعض الدين ويداريه في السداد، والآخر يحلف أنه لن يفعل. خرج النبي ﷺ إليهما، وسأل الرجل الذي أقسم ألا يساعد إن كان هو صاحب اليمين. فلما أجابه، حثه على المعروف، فقبل أن يعطي صاحبه ما طلب. لم يحتج الإصلاح إلى خصومة أكبر؛ احتاج إلى تدخل رحيم يذكّر بحق المحتاج وفضل التيسير.'},
  {id:'merchant-forgive',title:'تاجر يسامح من عجز عن السداد',source:'صحيح البخاري، حديث 2078',url:'https://sunnah.com/bukhari:2078',text:'من أخبار الأمم السابقة التي قصها النبي ﷺ رجل كان يطلب حقه من الناس، لكنه أوصى وكلاءه أن يرفقوا بالفقير إذا عجز. قال لهم إن وجدتموه معسرًا فتجاوزوا عنه، لعل الله يتجاوز عنا. لم يخلط بين حفظ الحق وإذلال صاحبه؛ أعطى المحتاج فرصة، ورجا رحمة الله. وفي نهاية الخبر غفر الله له. نعرض الحكاية كما ورد معناها دون أسماء أو تفاصيل من الخيال، ونتعلم أن العفو والتيسير بابان للرحمة.'},
  {id:'cave-parents',title:'الرجل الذي انتظر والديه بالحليب',source:'صحيح البخاري، حديث 2272',url:'https://sunnah.com/bukhari:2272',text:'في قصة الثلاثة الذين انغلقت عليهم صخرة في غار، دعا أحدهم الله بعمل صالح أخلص فيه. كان يعود كل ليلة بحليب غنمه، فيبدأ بوالديه الكبيرين قبل زوجته وأطفاله. وفي ليلة تأخر، فوجدهما نائمين، فكره أن يوقظهما، وكره أن يقدم على أهله قبلهما. ظل واقفًا يحمل الإناء ينتظر حتى استيقظا وشربا، وأطفاله يبكون عند قدميه. دعا الله بصدق، فتحركت الصخرة قليلًا. موقف يعلّم بر الوالدين والصبر على خدمتهم.'},
  {id:'cave-worker',title:'الرجل الذي حفظ أجر العامل',source:'صحيح البخاري، حديث 2272',url:'https://sunnah.com/bukhari:2272',text:'في خبر الرجال الثلاثة داخل الغار، حكى أحدهم أنه استأجر عاملًا، فلما انتهى العمل ترك أجره ومضى. لم ينسه الرجل، بل استثمر الأجر حتى نما وصار مالًا كثيرًا. وبعد زمن عاد العامل يطلب حقه، فأعطاه الرجل كل ما نتج من المال، ولم يأخذ لنفسه شيئًا منه. دعا الله أن يكون قد فعل ذلك ابتغاء مرضاته، فانفرجت الصخرة قليلًا. القصة تزرع قيمة حفظ الأمانة، وأن حق العامل لا يضيع مهما طال الزمن.'},
  {id:'cave-chastity',title:'الرجل الذي اختار العفة',source:'صحيح البخاري، حديث 2272',url:'https://sunnah.com/bukhari:2272',text:'حكى الرجل الثالث في قصة الغار أنه أحب ابنة عمه حبًا شديدًا، وطلب منها أمرًا لا يحل. احتاجت المرأة إلى المال فوافقت على شرط مئة دينار. وحين صار قادرًا على فعل ما أراد، ذكّرته بالله، فتوقف فورًا وترك لها المال الذي دفعه، ولم يأخذ منه شيئًا. دعا الله أن يكون قد ترك ذلك خوفًا منه، فتحركت الصخرة مرة أخرى حتى استطاعوا الخروج. موقف صعب يعلّم ضبط النفس واحترام كرامة الناس، والرجوع إلى الحق حين نتذكر الله.'},
  {id:'king-boy-faith',title:'الغلام الذي تمسك بالحق',source:'صحيح مسلم، حديث 3005',url:'https://sunnah.com/muslim:3005',text:'يروي صهيب رضي الله عنه قصة غلام في مملكة قديمة، أرسله الملك ليتعلم السحر من ساحر القصر. وفي طريقه كان يجلس إلى راهب يسمع منه عن عبادة الله، فآمن بما سمع. صار الغلام يردّ الأمر إلى الله، ويقول إنه وحده يشفي. غضب الملك وحاول أن يجبره على ترك إيمانه، لكن الغلام ظل ثابتًا. طلب الغلام أن يجمع الملك الناس ثم يقول إن الله هو الذي ينجيه؛ فكان ذلك سببًا في معرفة الناس بالحق. القصة طويلة ومروية في صحيح مسلم، ومغزاها الشجاعة والصدق.'},
  {id:'monk-boy',title:'الغلام يتعلم من الراهب',source:'صحيح مسلم، حديث 3005',url:'https://sunnah.com/muslim:3005',text:'كان الغلام في طريقه إلى الساحر حين مرّ براهب يسمع الناس منه. جذب انتباهه كلام الراهب، فصار يجلس إليه، ثم يتأخر عن موعده عند الساحر فيعاقبه الساحر. شكا الغلام ما يحدث للراهب، فنصحه أن يخبر الساحر أن أهله أخّروه، وأن يقول لأهله إن الساحر أخّره. كما علّمه ألا ينسب الشفاء إلى نفسه، فالله وحده يشفي. هكذا عاش الغلام بين طريقين، وتعلّم أن يميز الصدق ويثبت عليه. رواية صحيحة، لا نضيف فيها اسمًا لم يرد.'},
  {id:'king-boy-trial',title:'الغلام يواجه الملك',source:'صحيح مسلم، حديث 3005',url:'https://sunnah.com/muslim:3005',text:'استدعى الملك الغلام بعدما شاع بين الناس أن الله يشفي على يديه. سأله الملك عن ذلك، فأجابه الغلام أنه لا يشفي أحدًا بنفسه، وإنما الله هو الشافي. حاول الملك أن يضغط عليه ليترك إيمانه، لكن الغلام لم يبدل كلمته. أخذ الملك يختبره ويهدده، ومع ذلك بقي الغلام صادقًا فيما يعتقد. تتابع الرواية أحداثًا شديدة، لذا نحكي للأطفال أصل الموقف بلا وصف مؤذٍ: قوة الغلام جاءت من ثقته بالله وتمسكه بالحق، لا من سحر أو قوة جسدية.'},
  {id:'jurayj',title:'العابد جريج والطفل الذي تكلم',source:'صحيح البخاري، حديث 3436',url:'https://sunnah.com/bukhari:3436',text:'كان جريج رجلًا عابدًا، فدعته أمه وهو يصلي، فتساءل: أأجيبها أم أواصل صلاتي؟ تكرر الموقف، فدعت عليه أن يريه الله وجه المومسات، ثم جاءته امرأة وادعت عليه باطلًا. اتهمه الناس، وأهدموا صومعته، لكنه لم يصرخ ولم ينتقم. توضأ وصلى، ثم طلب رؤية الطفل، وسأله: من أبوك؟ فتكلم الطفل بإذن الله وذكر راعيًا. ظهرت براءة جريج، فعرض الناس أن يبنوا صومعته من ذهب، فطلب أن يعيدوها كما كانت. مغزى القصة التثبت قبل اتهام الناس.'},
  {id:'jurayj-testimony',title:'الطفل يشهد ببراءة جريج',source:'صحيح البخاري، حديث 3436',url:'https://sunnah.com/bukhari:3436',text:'بعد أن اتهم الناس جريجًا، طلب منهم أن يأتوا بالطفل. توضأ وصلى، ثم اقترب من الطفل وسأله عن أبيه، فأنطقه الله بالإجابة: أبي راعٍ. عرف الناس أن اتهامهم لجريج كان باطلًا، وندموا على ما صنعوا بصومعته. قالوا إنهم سيبنونها من ذهب، لكنه اختار أن تعود من طين كما كانت. لا تقول الرواية إن جريج كان نبيًا أو إن الطفل تكلم من تلقاء نفسه؛ بل تروي آية أظهر الله بها براءته. العبرة أن الحقيقة قد تظهر، فلا نتسرع في الظلم.'},
  {id:'solomon-mothers',title:'سليمان عليه السلام والطفل المختلف عليه',source:'صحيح البخاري، حديث 3426',url:'https://sunnah.com/bukhari:3426',text:'كان مع امرأتين طفلان، فأخذ الذئب طفل إحداهما، ثم اختلفتا في الطفل الباقي: كل واحدة تقول إنه ابنها. عرضتا الأمر على داود عليه السلام فقضى به للكبرى. ثم ذهبتا إلى سليمان عليه السلام، فاستمع إليهما وقال: ائتوني بسكين لأقسم الطفل بينكما. لم تكن هذه نيته، بل أراد أن يعرف من ستكشف محبتها الحقيقة. صاحت الأم الحقيقية أن يترك الطفل للأخرى ولا يؤذيه، فعرفها سليمان وأعطاها إياه. رواية صحيحة عن الحكمة والرحمة، ونحكيها دون مشهد مخيف.'},
  {id:'musa-khidr',title:'موسى والخضر: بداية الرحلة',source:'القرآن الكريم، سورة الكهف 60–82',url:'https://quran.com/18/60-82',text:'خرج موسى عليه السلام في رحلة ليتعلم من عبد صالح علّمه الله علمًا خاصًا. اصطحب معه فتاه يوشع، وحملا حوتًا علامة على المكان الذي سيجدانه فيه. عند صخرة ناما، ثم تحرك الحوت إلى البحر، ونسي الفتى أن يخبر موسى بذلك. واصلا طريقهما حتى تعبا، فطلب موسى الطعام، فتذكر الفتى الحوت. رجعا على آثارهما حتى وصلا إلى الصخرة، وهناك التقيا الخضر. بداية الرحلة تعلم الطفل أدب طلب العلم، والاستعداد للسفر، والاعتراف بالنسيان.'},
  {id:'musa-khidr-boat',title:'السفينة في رحلة موسى والخضر',source:'القرآن الكريم، سورة الكهف 60–82',url:'https://quran.com/18/60-82',text:'ركب موسى والخضر سفينة لقوم حملوهما عليها من غير مقابل. أحدث الخضر فيها عيبًا، فاستغرب موسى كيف يضر سفينة أناس أحسنوا إليهما. لم يكن موسى يعرف الحكمة التي يعلمها الله للخضر، فاعترض بحسب ما ظهر له. بعد ذلك شرح الخضر أن ملكًا ظالمًا كان يأخذ السفن السليمة، فأراد أن تبقى هذه السفينة لأهلها بعيب صغير. القصة لا تعلمنا إتلاف الممتلكات، بل تروي موقفًا خاصًا في رحلة نبي، وتذكّرنا أن بعض الأمور لا تتضح حكمتها فورًا.'},
  {id:'musa-khidr-knowledge',title:'موسى يتعلم التواضع في طلب العلم',source:'القرآن الكريم، سورة الكهف 60–82',url:'https://quran.com/18/60-82',text:'أخبر الخضر موسى عليه السلام منذ البداية أن موسى لن يستطيع الصبر على ما لا يعرف حكمته. وافق موسى أن يصبر ولا يسأل حتى يشرح له صاحبه. لكن الأحداث كانت تبدو غريبة، فكان موسى يسأل؛ لأنه يرى ظاهر الموقف ويريد معرفة الحق. وبعد انتهاء الرحلة، فسّر الخضر ما جرى، ثم افترقا. لم يكن موسى قليل العلم، لكنه تعلم أن علم الإنسان محدود وأن التعلم يحتاج صبرًا وسؤالًا في وقته. هذا المعنى ثابت في رواية البخاري وقصة سورة الكهف.'},
  {id:'musa-angel',title:'موسى عليه السلام ومَلَك الموت',source:'صحيح البخاري، حديث 3407',url:'https://sunnah.com/bukhari:3407',text:'قصّ النبي ﷺ على أصحابه خبر موسى عليه السلام حين جاءه مَلَك الموت. جاءه المَلَك، فطلب موسى من الله أن يؤخر أجله، ثم خيّره الله في علامة يعرف بها قرب أجله. سأل موسى أن يكون قريبًا من الأرض المقدسة، قدر رمية حجر. وذكر النبي ﷺ أنه لو كان هناك لأراهم قبر موسى عند الكثيب الأحمر. نروي الحديث بلطف وبلا تفاصيل مخيفة؛ فهو يذكّر أن الأنبياء بشر، وأن لكل إنسان أجلًا يعلمه الله.'},
  {id:'cloud-charity',title:'سحابة تسقي أرض رجل أمين',source:'صحيح مسلم، حديث 2984a',url:'https://sunnah.com/muslim:2984a',text:'سمع رجل صوتًا في سحابة يأمرها أن تسقي أرض فلان. تبع السحابة حتى أمطرت في أرض، فوجد الماء يسيل في قناة إلى بستان. سأل صاحب البستان عن اسمه، فأجابه الرجل باسم مطابق لما سمع. أخبره صاحب البستان أنه يقسم محصوله ثلاثة أقسام: جزء يتصدق به، وجزء يأكله أهله، وجزء يعيده إلى الأرض. يروي الحديث كيف بارك الله في عمل صاحب الأرض وصدقته. القصة تشجع على الأمانة ومشاركة النعمة، دون أن نضيف سببًا غير الذي ذكره النص.'},
  {id:'hundred-killer',title:'رجل يطلب طريق التوبة',source:'صحيح مسلم، حديث 2766',url:'https://sunnah.com/muslim:2766',text:'كان رجل قد ارتكب ذنوبًا عظيمة، ثم أراد أن يتوب، فسأل عن أعلم أهل الأرض. دلّوه على عابد، فسأله هل له توبة، فأساء العابد وأجابه بالنفي، فتمادى الرجل في خطئه. ثم دلّوه على عالم، فسأله السؤال نفسه، فأجابه أن باب التوبة مفتوح، ونصحه أن يترك أرض السوء ويذهب إلى قوم صالحين يعينونه. بدأ الرجل الرحلة، لكنه مات في الطريق. اختلفت ملائكة الرحمة والعذاب في شأنه، فقضى الله له بالرحمة لقربه من أرض الصالحين. القصة تقول بوضوح: لا تيأس من التوبة واطلب صحبة تعينك.'},
  {id:'merchant-debt',title:'رجل تجاوز عن المعسرين',source:'صحيح البخاري، حديث 2078',url:'https://sunnah.com/bukhari:2078',text:'كان فيمن قبلنا رجل يعمل في التجارة ويقرض الناس، لكنه لم يكن قاسيًا على من ضاقت به الحال. أوصى من يعملون معه أن يتجاوزوا عن المعسر، أو يخففوا عنه، رجاء أن يتجاوز الله عنهم يوم القيامة. لما مات، سأله الله عما قدمه، فقال إنه لم يكن يملك عملًا غير هذا، لكنه كان ييسّر على الناس. فعفا الله عنه. هذه الحكاية الموثقة تضع أمام الطفل اختيارًا بين التشدد والرحمة، وتعلمه أن القوي يستطيع أن يساعد من تعثر.'},
  {id:'camel-complaint',title:'النبي ﷺ يسمع شكوى الجمل',source:'سنن أبي داود، حديث 2549 — صححه الألباني',url:'https://sunnah.com/abudawud:2549',text:'دخل النبي ﷺ بستانًا لرجل من الأنصار، فرأى جملًا، فلما رأى الجمل النبي ﷺ حنّ وذرفت عيناه. اقترب منه النبي ﷺ ومسح عليه حتى هدأ، ثم سأل عن صاحبه. جاء شاب من الأنصار، فأخبره النبي ﷺ أن الجمل يشكو كثرة العمل وقلة العلف، وأمره أن يتقي الله فيه. لا تصف الرواية بكلمات مخترعة ما قاله الجمل، لكنها تنقل أن النبي فهم شكواه ونصح مالكه بالرحمة. حكاية عن الإصغاء إلى الضعيف والاهتمام بالحيوان العامل.'},
  {id:'bird-chicks',title:'النبي ﷺ يعيد فراخ الطائر إلى أمها',source:'سنن أبي داود، حديث 2675',url:'https://sunnah.com/abudawud:2675',text:'كان أصحاب النبي ﷺ في سفر، فرأوا طائرًا ومعه فرخان، فأخذ بعضهم الفرخين. جاءت أم الطائر ترفرف بجناحيها من شدة القلق، فلما علم النبي ﷺ بما حدث قال: من فجع هذه بولدها؟ ردوا ولدها إليها. أعاد الصحابة الفرخين، فعادت الأم إليهما. وفي الموقف نهى النبي ﷺ عن اتخاذ الحيوان هدفًا للعب واللهو. قصة حقيقية قصيرة المشهد واضحة المعنى: الأم تحزن على صغيرها، والرحمة تقتضي إعادة الطفل إلى أمه وعدم إيذاء الحيوانات.'},
  {id:'bedouin-cloak',title:'النبي ﷺ يرفق بأعرابي طلب عطاء',source:'صحيح البخاري، حديث 3149',url:'https://sunnah.com/bukhari:3149',text:'كان النبي ﷺ يسير وعليه برد نجراني غليظ الحاشية، فلحقه أعرابي وجذبه من ردائه بقوة حتى أثّر طرفه في عنق النبي ﷺ. ثم طلب منه أن يعطيه من مال الله. لم يرد النبي ﷺ بإيذاء الرجل أو الانتقام، بل التفت إليه وضحك، ثم أمر أن يُعطى. ننقل الحدث كما جاء في الصحيح، من غير تبرير للخشونة أو تقليدها. المغزى أن الحلم والكرم قد يهدئان الموقف، وأن صاحب الخلق الحسن لا يجعل الإساءة الصغيرة سببًا للانتقام.'},
  {id:'khandaq-food',title:'جابر يدعو النبي ﷺ إلى طعام قليل',source:'صحيح البخاري، حديث 4101',url:'https://sunnah.com/bukhari:4101',text:'رأى جابر بن عبد الله رضي الله عنهما أثر الجوع على النبي ﷺ يوم الخندق، فعاد إلى بيته وأخبر زوجته بما رأى. لم يكن عندهما إلا قليل من شعير وشاة صغيرة، فصنعا طعامًا ودعوا النبي ﷺ سرًا. لكن النبي ﷺ أعلن لأهل الخندق أن جابرًا صنع طعامًا، ودعاهم جميعًا. خاف جابر من قلة الطعام، غير أن النبي ﷺ رتّب دخول الناس، فأكلوا حتى شبعوا وبقي الطعام. تروي الرواية كرم جابر وبركة الطعام، وحرص النبي على ألا يترك أصحابه جائعين.'},
  {id:'repayment-camel',title:'النبي ﷺ يرد الدين بأحسن منه',source:'صحيح البخاري، حديث 2606',url:'https://sunnah.com/bukhari:2606',text:'كان للنبي ﷺ دَين عند رجل، فجاء الرجل يطلب حقه بشدة في كلامه. غضب بعض الصحابة من طريقته، لكن النبي ﷺ طلب منهم أن يتركوه، فصاحب الحق له أن يطالب به. ثم أمر أن يشتروا له بعيرًا مماثلًا لما أخذه. بحثوا فلم يجدوا إلا بعيرًا أكبر عمرًا وأفضل، فأمر النبي ﷺ أن يعطوه إياه، وبيّن أن أحسن الناس من يرد الدين بأفضل طريقة. موقف صحيح يجمع حفظ الحق وحسن الخلق، ويعلمنا أن نؤدي الأمانة كاملة.'},
  {id:'ibrahim-cry',title:'النبي ﷺ يودّع ابنه إبراهيم',source:'صحيح البخاري، حديث 1303',url:'https://sunnah.com/bukhari:1303',text:'مرض إبراهيم ابن النبي ﷺ، وكان النبي يذهب إليه ويأخذه ويقبله. وعندما حضرته الوفاة حمله إلى صدره، ودمعت عيناه. استغرب عبد الرحمن بن عوف رضي الله عنه البكاء، فقال له النبي ﷺ إن العين تدمع والقلب يحزن، لكنه لا يقول إلا ما يرضي الله. ثم ودّع ابنه بكلمات رحيمة. الحديث يعلّم الأطفال أن الحزن على فراق الأحبة أمر إنساني، وأن الرحمة لا تنافي الصبر، ولا ينبغي أن نخجل من الدموع ما دمنا نتكلم بأدب.'},
  {id:'prophet-child-cry',title:'النبي ﷺ يخفف الصلاة رحمة بأم طفل',source:'صحيح البخاري، حديث 707',url:'https://sunnah.com/bukhari:707',text:'أخبر النبي ﷺ أنه يدخل في الصلاة وهو يريد أن يطيلها، ثم يسمع بكاء طفل، فيخفف الصلاة؛ لأنه يعرف أن بكاءه يشق على أمه. تخيلوا الموقف: أم تقف تصلي وقلبها مع طفلها، فيراعي النبي ﷺ شعورها ولا يطيل عليها. لم يقل لها إن عليها أن تتحمل وحدها، بل جعل رحمتها جزءًا من تقديره في العبادة. هذه القصة من الحديث الصحيح، وتعلمنا أن ننتبه لمشاعر الآخرين، وأن القائد الرحيم يراعي الضعيف والصغير.'},
  {id:'prophet-animals',title:'الرحمة بالحيوانات في السفر',source:'سنن أبي داود، حديث 2675',url:'https://sunnah.com/abudawud:2675',text:'في سفر الصحابة، رأى النبي ﷺ أن طائرًا فقد صغيريه بعدما أخذهما بعض المسافرين. لم يترك المشهد يمرّ بلا توجيه، وسأل من فجع الطائر بولده، ثم أمر بإعادة الفرخين إلى مكانهما. يختصر الحديث الموقف في كلمات قليلة، لكن الطفل يفهمه بسهولة: الطائر أم، وصغارها يحتاجون إليها. لذلك ينبغي أن نلعب من غير إيذاء، وألا نأخذ صغار الحيوان من أعشاشها. حكاية موثقة عن احترام حياة المخلوقات والرحمة بها.'},
  {id:'mercy-all',title:'الرحمة تشمل كل حي',source:'صحيح البخاري، حديث 2466',url:'https://sunnah.com/bukhari:2466',text:'سأل الصحابة النبي ﷺ: هل لنا في الإحسان إلى الحيوانات أجر؟ فأجابهم أن في كل كبد رطبة أجرًا؛ أي إن الإحسان إلى كل مخلوق حي يؤجر عليه صاحبه. وتوضح أحاديث أخرى هذا المعنى بقصص الرجل والكلب العطشان والطائر وفراخه. لا نضيف قصة مخترعة، بل نجمع المعنى الذي جاءت به الروايات الصحيحة: سقيا الماء، والطعام، وعدم الإيذاء كلها أعمال رحمة. المغزى العملي للطفل أن يعامل الحيوان بلطف ويطلب مساعدة كبير إذا وجده جائعًا أو مصابًا.'},
  {id:'mosque-kindness',title:'النبي ﷺ يعلم الرفق في موقف صعب',source:'صحيح البخاري، حديث 6128',url:'https://sunnah.com/bukhari:6128',text:'دخل أعرابي المسجد، ولم يكن يعرف أحكام المكان، ففعل أمرًا أزعج الصحابة. قاموا إليه ليمنعوه بعنف، لكن النبي ﷺ أوقفهم، ثم شرح لهم أن الناس بُعثوا ميسّرين لا معسّرين. وبعد أن انتهى الرجل، أمر النبي بصب الماء على الموضع، ثم علّمه برفق أن المساجد للصلاة وذكر الله. لا يصح أن نكرر الفعل، لكن القصة تشرح كيف نصح النبي الجاهل من غير إهانة أو صراخ، وكيف نصلح الخطأ بهدوء.'},
  {id:'neighbor-cat',title:'حق الحيوان الذي في بيتك',source:'صحيح البخاري، حديث 3318',url:'https://sunnah.com/bukhari:3318',text:'من قصة القطة التي حبستها امرأة، نتعلم أن مسؤولية الرعاية لا تنتهي عندما ننشغل أو نمل. القطة لم تكن قادرة على فتح الباب أو البحث عن طعامها، فكان على من حبسها أن يطعمها أو يتركها تذهب. أهملتها المرأة فكان ذلك سببًا في العقوبة. نعرض هذا الخبر كحكاية تعليمية مستندة إلى حديث صحيح، لا كقصة تسلية عن حيوان يتكلم. المغزى أن الضعيف الذي نعوله أمانة، سواء كان طفلًا أو حيوانًا.'},
  {id:'musa-patience',title:'موسى والخضر: الصبر قبل الحكم',source:'القرآن الكريم، سورة الكهف 60–82',url:'https://quran.com/18/60-82',text:'في رحلتهما، رأى موسى عليه السلام أفعالًا لم يفهم حكمتها، فكان يسأل الخضر عنها. لم يكن السؤال عيبًا؛ كان موسى يريد أن يعرف، لكنه نسي الشرط الذي اتفقا عليه: أن يصبر حتى يسمع التفسير. بعد كل سؤال، ذكّره الخضر بما وعد. وفي نهاية الرحلة شرح له ما خفي من أسباب الأحداث. القصة لا تطلب منا السكوت عن الخطأ، لكنها تعلمنا ألا نحكم على أمر قبل معرفة المعلومات، وأن نسأل بأدب ونصبر حتى تكتمل الصورة.'},
  {id:'solomon-mother',title:'رحمة الأم تكشف الحقيقة',source:'صحيح البخاري، حديث 3426',url:'https://sunnah.com/bukhari:3426',text:'في مجلس سليمان عليه السلام، ادعت امرأتان أن الطفل الحي ابن كل واحدة منهما. اقترح سليمان أن يقسمه بينهما، فعرفت الأم الحقيقية أن حياة الطفل أهم من أن تكسب القضية لنفسها، فطلبت أن تتركه للأخرى. عندها ظهرت محبتها، فأعطاها سليمان الطفل. ليس في الرواية وصف لسلاح أو تنفيذ؛ كان هذا سؤالًا كشف الحقيقة لا فعلًا وقع. نتعلم أن المحبة الصادقة تقدم سلامة من تحب على المكسب، وأن الحكمة قد تحتاج إلى فهم القلوب.'},
  {id:'khalid-justice',title:'جابر يسدد ديون أبيه',source:'صحيح البخاري، حديث 2127',url:'https://sunnah.com/bukhari:2127',text:'بعد وفاة عبد الله بن عمرو بن حرام، والد جابر رضي الله عنهما، بقيت عليه ديون لأناس. لم يكن عند جابر إلا تمر بستان أبيه، وكان يخشى ألا يكفي لسداد الحقوق. طلب من النبي ﷺ أن يكلم أصحاب الديون ليخففوا، لكنهم لم يوافقوا. رتّب النبي ﷺ أنواع التمر في أكوام، ثم طلب من جابر أن يقيس لكل دائن حقه. ظل يقيس حتى وفّى الديون كلها، وبقي التمر كما هو لم ينقص. يحكي جابر موقفًا فيه حرص على رد الحقوق، ومساندة النبي له في وقت ضيق.'},
  {id:'prophet-lost-camel',title:'جابر يتعلم الوفاء بالشرط',source:'صحيح البخاري، حديث 2718',url:'https://sunnah.com/bukhari:2718',text:'حين باع جابر رضي الله عنه جمله للنبي ﷺ، اشترط أن يظل راكبًا عليه حتى يصل إلى المدينة؛ فقد كان عائدًا إلى أهله. وافق النبي ﷺ على الشرط، فلم يأخذه منه في الطريق. وبعد وصولهما، دفع له الثمن ثم أعاد له جمله هدية. يروي جابر الموقف ليبين كرم النبي ﷺ ووفاءه بما اتفقا عليه. حكاية مناسبة للأطفال عن البيع العادل: نتفق بوضوح، ونحترم الشروط، ولا نأخذ حق أحد حتى لو كنا نقدر عليه.'},
  {id:'surah-read',title:'القراءة أول ما نزل من الوحي',source:'صحيح البخاري، حديث 3',url:'https://sunnah.com/bukhari:3',text:'في غار حراء، نزلت أول آيات الوحي بكلمة «اقرأ». كان النبي ﷺ أميًا لا يقرأ من كتاب، ومع ذلك جاءه الأمر بالقراءة والتعلم باسم الله الذي خلق. عاد إلى بيته يخبر خديجة بما وقع، فكانت أول من آمن به وسانده. لا تقول الرواية إن النبي كان يتعلم القراءة في الغار، بل تحكي بداية الرسالة وأول آياتها. المغزى الذي يناسب أطفال الحضانة هو حب العلم، وأن القراءة باب مهم لمعرفة العالم والتقرب إلى الله.'},
  {id:'hijra-planning',title:'خطة الهجرة وأخذ الأسباب',source:'صحيح البخاري، حديث 3905',url:'https://sunnah.com/bukhari:3905',text:'لم تكن الهجرة سفرًا عشوائيًا. اختار النبي ﷺ وأبو بكر رضي الله عنه طريقًا ومخبأ، واستعانا بدليل يعرف الطرق، واتفقا أن يأتيهما في موعد محدد بالراحلتين. وكان عبد الله يأتيهما بالأخبار، وأسماء تحضر الزاد، وعامر بن فهيرة يرعى الغنم قرب الطريق. كل شخص أدى مهمة مختلفة. يروي الحديث هذه التفاصيل لنعرف أن التوكل على الله يجتمع مع التخطيط والعمل وتوزيع المسؤوليات، وأن نجاح الفريق يحتاج إلى الثقة وحفظ السر.'},
  {id:'good-neighbor',title:'حق الجار عند أبي طلحة',source:'صحيح البخاري، حديث 3798',url:'https://sunnah.com/bukhari:3798',text:'حين استضاف أبو طلحة ضيفًا، لم يكن لديه طعام يكفي الجميع. فكرت زوجته معه في طريقة لتقديم الطعام للضيف، فغطيا قلة الطعام وأطعماه، بينما نام الأطفال جائعين. في الصباح أخبر النبي ﷺ أبا طلحة أن الله رضي عن صنيعهما. لا نطلب من الأطفال أن يحرموا أنفسهم من الطعام، لكن نتعلم أن الكبار قد يختارون الإيثار عن رضا، وأن إكرام الضيف من الخصال الجميلة. وفي الحياة اليومية نكرم ضيفنا بما نستطيع بلا إسراف ولا تكلف.'},
  {id:'kind-word',title:'الكلمة الطيبة صدقة',source:'صحيح البخاري، حديث 2989',url:'https://sunnah.com/bukhari:2989',text:'علّم النبي ﷺ أصحابه أن أبواب الخير كثيرة، وأن الكلمة الطيبة صدقة. لا تروي هذه الرواية حادثة لشخص واحد، لكنها تفتح حكاية نعيشها كل يوم: طفل يواسي صديقه إذا حزن، أو يشكر من ساعده، أو يعتذر إذا أخطأ. هذه الكلمات لا تحتاج مالًا، لكنها تترك أثرًا طيبًا في القلوب. المصدر حديث صحيح عن أبي هريرة رضي الله عنه. المغزى أن اللسان يستطيع أن يفرح الناس، لذلك نختار كلمات رحيمة وصادقة.'},
  {id:'smile-sadaqa',title:'البشاشة في وجه أخيك',source:'جامع الترمذي، حديث 1956 — حسن صحيح',url:'https://sunnah.com/tirmidhi:1956',text:'كان أصحاب النبي ﷺ يتعلمون أن المعروف لا يحتاج دائمًا إلى مال. أخبرهم النبي ﷺ أن تبسم الإنسان في وجه أخيه صدقة. تخيل طفلًا يدخل الحضانة خائفًا فيستقبله صديقه بابتسامة، أو أمًا يحييها أحد بكلمة لطيفة؛ قد تتحول اللحظة الصغيرة إلى بداية يوم سعيد. هذا معنى نبوي ثابت، وليس قصة منسوبة لشخص لم يرد اسمه. المغزى أن البشاشة واللطف هدية مجانية نستطيع تقديمها كل يوم.'},
  {id:'help-mount',title:'مساعدة المسافر على راحلته',source:'صحيح البخاري، حديث 2989',url:'https://sunnah.com/bukhari:2989',text:'عدّ النبي ﷺ من أعمال الخير أن يعين المرء أخاه فيركبه على دابته أو يرفع له متاعه. كانت الرحلات قديمًا تتم على الدواب، وكان المسافر يحتاج من يساعده في الركوب والحمل. تخبرنا الرواية أن هذا الجهد العملي صدقة، حتى لو لم يدفع صاحبه مالًا. وفي يومنا يمكن أن نترجم المعنى إلى مساعدة شخص يحمل حقيبة، أو فتح الطريق لمن يحتاج، أو حمل أغراض البيت مع الأسرة. المغزى أن التعاون اليومي عبادة وعمل محبب.'},
  {id:'greet-children',title:'النبي ﷺ يلقي السلام على الصغار',source:'صحيح البخاري، حديث 6247',url:'https://sunnah.com/bukhari:6247',text:'كان أنس بن مالك رضي الله عنه يمر على الصبيان فيسلم عليهم، ويذكر أن النبي ﷺ كان يفعل ذلك. قد يظن بعض الكبار أن الطفل صغير فلا يحتاج إلى أن يُلتفت إليه، لكن النبي ﷺ كان يبدأ الأطفال بالتحية ويشعرهم بقيمتهم. تخيلوا مجموعة أطفال يلعبون في الطريق، فيمر بهم النبي فيسلم عليهم؛ إن هذا الخلق البسيط يجعل الطفل يشعر بالاحترام والانتماء. نتعلم أن نلقي السلام بأدب، ونرحب بالصغير كما نرحب بالكبير.'},
  {id:'anas-years',title:'أنس يخدم النبي ﷺ عشر سنوات',source:'صحيح البخاري، حديث 6038',url:'https://sunnah.com/bukhari:6038',text:'بدأ أنس بن مالك رضي الله عنه خدمة النبي ﷺ وهو صغير، وبقي معه عشر سنوات. وبعد هذه السنين الطويلة، شهد أن النبي ﷺ لم يقل له كلمة تضجر، ولم يلمه على ما فعل أو ترك بعبارة قاسية. هذه شهادة طفل عاش قرب النبي في تفاصيل الحياة اليومية، لا خبر عابر. لنتخيل كم مرة يمكن أن يخطئ طفل في عشر سنوات؛ ومع ذلك تذكر أنس الرفق. القصة تعلم المربي أن يصحح الخطأ بهدوء، وأن الاحترام يصنع علاقة آمنة.'},
  {id:'kindness-animal',title:'النبي ﷺ يوصي بالرفق في كل شيء',source:'صحيح مسلم، حديث 1955',url:'https://sunnah.com/muslim:1955',text:'كان النبي ﷺ إذا رأى حيوانًا يحمل حملًا ثقيلًا أو يُعامل بقسوة، وجّه أصحابه إلى الرفق به. وفي حديث صحيح قال إن الله كتب الإحسان على كل شيء، حتى عند الذبح يجب أن يكون العمل برفق. نعرض للطفل المعنى المناسب لعمره: لا نضرب الحيوان، ولا نخيفه، ونقدم له الماء والطعام بإذن الكبار. لا نضيف مشهدًا غير موجود في الرواية؛ بل نأخذ منها قاعدة الرحمة العامة. المغزى أن الرفق ليس مع الأصدقاء فقط، بل مع كل مخلوق.'},
  {id:'truth-kab',title:'كعب بن مالك يختار الصدق',source:'صحيح البخاري، حديث 4418',url:'https://sunnah.com/bukhari:4418',text:'تخلّف كعب بن مالك رضي الله عنه عن غزوة تبوك بلا عذر، ثم عاد النبي ﷺ إلى المدينة. كان يستطيع أن يخترع حجة، لكنه اختار أن يقول الحقيقة. سأله النبي ﷺ عما منعه، فأخبره كعب بصدق أنه لم يكن قط أقوى ولا أيسر حالًا مما كان يومها. أمر النبي ﷺ الناس أن ينتظروا حكم الله فيه، فمر عليه وقت صعب، لكنه لم يتراجع عن الصدق. ثم أنزل الله توبته وقبلها. القصة طويلة في صحيح البخاري، ومغزاها أن الصدق قد يكون شاقًا لكنه طريق النجاة.'},
  {id:'kaab-repentance',title:'فرحة كعب بن مالك بالتوبة',source:'صحيح البخاري، حديث 4418',url:'https://sunnah.com/bukhari:4418',text:'بعد أن صدق كعب بن مالك النبي ﷺ في سبب تخلفه، عاش أيامًا ينتظر فرج الله. ثم جاءه من يبشره بقبول التوبة، فسجد شكرًا لله، وذهب إلى النبي ﷺ فرحًا. قال كعب إن أعظم ما أنعم الله به عليه بعد الإسلام هو صدقه يومها؛ لأنه لو كذب لهلك كما هلك الذين كذبوا. أمره النبي ﷺ أن يحتفظ بماله، فتصدق ببعضه شكرًا لله. لا نخفي أن الموقف كان صعبًا، لكن نهايته فرح ورحمة، وفيه درس أن الاعتراف بالخطأ بداية الإصلاح.'},
  {id:'cave-rock',title:'ثلاثة مسافرين والصخرة الكبيرة',source:'صحيح البخاري، حديث 2272',url:'https://sunnah.com/bukhari:2272',text:'خرج ثلاثة رجال في سفر، فأدركهم المطر، فدخلوا غارًا يحتمون به. سقطت صخرة كبيرة فأغلقت مدخل الغار، فعجزوا عن الخروج. قالوا إن الذي ينجيهم أن يدعوا الله بعمل صالح أخلصوا فيه. بدأ كل واحد يذكر عملًا صادقًا: بر الوالدين، وحفظ أجر العامل، وترك الحرام خوفًا من الله. مع كل دعاء تحركت الصخرة قليلًا، حتى انفتح الطريق وخرجوا سالمين. هذه القصة التي رواها النبي ﷺ تجمع ثلاث مواقف في حبكة واضحة عن الأمانة والبر والعفة.'},
  {id:'judgment-solomon',title:'حكمة سليمان عليه السلام في القضاء',source:'صحيح البخاري، حديث 3426',url:'https://sunnah.com/bukhari:3426',text:'حين اختلفت المرأتان على الطفل، لم يكتف سليمان عليه السلام بسماع كل واحدة تقول إنه ابنها، بل فكّر في طريقة تكشف الحقيقة من غير أن يؤذي الطفل. قال إنه سيقسمه، فظهرت على الفور مشاعر الأم الحقيقية، وطلبت أن يعيش الطفل ولو مع الأخرى. عندئذ عرف سليمان لمن يعطيه. كان الحكم قائمًا على ملاحظة الرحمة، لا على الصوت الأعلى أو الادعاء الأقوى. حكاية موثقة تذكّرنا أن القاضي يحتاج إلى فهم وبصيرة، وأن سلامة الضعيف أولى من رغبة المتخاصمين.'},
  {id:'first-migration-cave',title:'الغار محطة في طريق الهجرة',source:'صحيح البخاري، حديث 3905',url:'https://sunnah.com/bukhari:3905',text:'في طريق الهجرة، لم يتجها مباشرة إلى المدينة من الطريق المعتاد، بل مكث النبي ﷺ وأبو بكر في غار ثور حتى يقل طلب قريش لهما. كان أبو بكر يراقب ما حولهما، وابنه يأتي بالأخبار، وابنته تحمل الزاد، وعامر بن فهيرة يمر بالغنم. وبعد أن هدأ البحث، استأجرا دليلًا أمينًا للطريق. هكذا اجتمعت الحيطة والعمل الجماعي والثقة بالله. القصة ليست مشهدًا واحدًا من بطولة شخص، بل تعاون عائلة كاملة في رحلة شديدة الأهمية.'},
  {id:'kind-debtor-prophet',title:'التيسير على المدين خُلُق نبوي',source:'صحيح البخاري، حديث 2705',url:'https://sunnah.com/bukhari:2705',text:'لم يترك النبي ﷺ رجلين يتنازعان على دين عند بابه، بل خرج إليهما واستمع إلى ما يطلبه كل طرف. كان أحدهما متعثرًا يرجو تخفيف المبلغ، والآخر قد حلف ألا يساعده. ذكّره النبي ﷺ أن التراجع عن اليمين إلى البر خير، فقبل أن يخفف عنه. لا نعرف أسماء الرجلين، لذلك لا نخترعها. لكننا نعرف النتيجة التي نقلتها عائشة رضي الله عنها: انتهى النزاع إلى التسامح. المغزى أن حل الخلاف يبدأ بالاستماع، وقد تغير نصيحة هادئة قرارًا قاسيًا.'},
  {id:'hajar-trust',title:'هاجر تثق بوعد الله',source:'صحيح البخاري، حديث 3364',url:'https://sunnah.com/bukhari:3364',text:'حين ترك إبراهيم عليه السلام هاجر وإسماعيل في وادٍ لا ماء فيه، لم تتبع هاجر الظنون، بل سألته إن كان الله قد أمره بذلك. فلما أجابها بنعم، اطمأن قلبها وقالت إن الله لن يضيعهما. لم يكن هذا انتظارًا بلا عمل؛ فبعد نفاد الماء ركضت بين الصفا والمروة تبحث عن الغوث، ثم جمعت ماء زمزم. القصة تجمع توكلًا عمليًا وشجاعة أم تحمي طفلها. نتعلم أن الثقة بالله تمنح القلب قوة، وأن علينا أن نتحرك ونطلب المساعدة أيضًا.'},
  {id:'guest-sharing',title:'ضيف واحد وطعام يكفي الجميع',source:'صحيح البخاري، حديث 3798',url:'https://sunnah.com/bukhari:3798',text:'كان الطعام في بيت أبي طلحة قليلًا، والضيف جائع، والأطفال ينتظرون وجبتهم. لم يتظاهر أبو طلحة بأن لديه الكثير؛ اتفق مع زوجته أن يقدموا ما عندهم للضيف، وأن يجعلوا الضوء خافتًا حتى يأكل مطمئنًا. في الصباح عرف النبي ﷺ بما فعلا وبشرهما برضا الله. هذه القصة الحقيقية لا تطلب من الطفل أن يجوع، لكنها تعرفه على الإيثار الذي يختاره الكبير عن طيب نفس، وعلى أن الضيافة ليست في كثرة الطعام بل في حسن الاستقبال.'},
  {id:'animal-water',title:'رجل يملأ خفه ليسقي كلبًا',source:'صحيح البخاري، حديث 2363',url:'https://sunnah.com/bukhari:2363',text:'عاد الرجل إلى البئر مرة ثانية بعد أن رأى الكلب يلهث ويأكل التراب من شدة العطش. نزل إلى الماء، وملأ خفه، ثم أمسكه بفمه وصعد حتى سقى الحيوان. ذكر النبي ﷺ أن الله شكر له عمله وغفر له، ثم أجاب الصحابة أن في الإحسان إلى كل حيوان أجرًا. نروي هذا الموقف باعتباره تفصيلًا مستقلًا من الرواية الصحيحة، ليرى الطفل أن الرحمة تحتاج أحيانًا إلى تعب ومحاولة، لا إلى شعور فقط. ونتعلم أن سقيا الماء من صور الإحسان.'},
];


